for(const e of LAY)if(t>=e[0]&&t<e[1])K.tx('tag.l','chrome',48,64,e[2],{size:14,fill:C.muted,role:'secondary',ls:1,op:tg*sm(seg(t,e[0],e[0]+ 0.4))});
